mapper.select:
SELECT id, conversation_id, user_id, role, content, message_type,
       feedback, dish_ids, tokens_used, is_deleted, create_time, tenant_id
FROM ai_message
WHERE conversation_id = #{conversationId}
  AND tenant_id = #{tenantId}
  AND is_deleted = #{isDeleted}
ORDER BY create_time ASC

SELECT content
FROM ai_message
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND role = 'user'
  AND is_deleted = 0
  AND content LIKE CONCAT(#{prefix}, '%')
  AND CHAR_LENGTH(content) BETWEEN 4 AND 100
ORDER BY id DESC
LIMIT #{limit}
